        let mut b = Held::new(Tool::round_sable(1.8), 80);
        // perched: on level-ish live points of order-1/2 limbs
        let mut perches: Vec<(f32, f32)> = Vec::new();
        for l in big.limbs.iter().filter(|l| (l.order == 1 || l.order == 2) && l.pts.len() > 3) {
            let i = l.pts.len() / 2;
            if l.dir(i).1.abs() < 0.5 && l.pts[i].1 < 300.0 {
                perches.push((l.pts[i].0, l.pts[i].1 - l.w[i] * 0.5));
            }
        }
        for (k, p) in perches.iter().take(4).enumerate() {
            let sz = 3.6;
            b.reload(crow, 0.8);
            let tail = if k % 2 == 0 { 1.0 } else { -1.0 };
            c.drag(&mut b, &Gesture::new(vec![(p.0 - tail * sz * 0.9, p.1 - sz * 0.4), (p.0, p.1 - sz * 0.9), (p.0 + tail * sz * 0.5, p.1 - sz * 1.6)]).pressure(0.8, 0.5).ramps(0.1, 0.4).shake(0.3), None);
            c.touch(&mut b, &Touch::at(p.0 + tail * sz * 0.55, p.1 - sz * 1.75).pressure(0.5), None);
        }
        for &(x, y, sz) in &[(705.0f32, 205.0f32, 6.0f32), (745.0, 232.0, 5.0)] {
            for side in [-1.0f32, 1.0] {
                b.reload(crow, 0.7);
                let tip = (x + side * sz, y - sz * 0.35);
                let mid = (x + side * sz * 0.45, y - sz * 0.45);
                c.drag(&mut b, &Gesture::new(vec![(x, y), mid, tip]).pressure(0.7, 0.0).ramps(0.1, 0.75).shake(0.5), None);
            }
        }
        c.dry();
    }

    // ---- dry grass and weeds through the snow, flicked upward, last
    if o.stage("grass", &mut c, &mut rng) {
        let dens = Fbm::new(41, 3, 90.0);
        let straw = pal.paint(hex("#7a6647"), 0.15);
        let brown = pal.paint(hex("#4a3d2e"), 0.15);
        let mut rg = Held::new(Tool::rigger(0.8), 90);
        let mut sb = Held::new(Tool::round_sable(1.2), 91);
        let mut n = 0;
        for _ in 0..900 {
            let x = rng.range(-10.0, 1010.0);
            let y = rng.range(520.0, h + 5.0);
            if y < knoll(x) + 20.0 || dens.get(x, y) < 0.15 {
                continue;
            }
            // the man's spot stays clear
            if (x - 402.0).abs() < 18.0 && y > 550.0 && y < 610.0 {
                continue;
            }
            let near = smoothstep(520.0, h, y);
            let blades = 3 + (rng.f() * 6.0) as usize;
            for _ in 0..blades {
                let ht = (4.0 + 14.0 * rng.f()) * (0.4 + near);
                let lean = rng.range(-0.45, 0.45) + 0.15;
                let bx = x + rng.range(-3.0, 3.0) * (0.5 + near);
                let pts = vec![(bx, y), (bx + lean * ht * 0.3, y - ht * 0.55), (bx + lean * ht, y - ht)];
                let hb = if n % 3 == 0 { &mut sb } else { &mut rg };
                hb.reload(if n % 2 == 0 { straw } else { brown }, 0.6);
                c.drag(hb, &Gesture::new(pts).pressure(0.7, 0.0).ramps(0.04, 0.8).shake(0.5), None);
                n += 1;
            }
        }
        c.dry();
    }

    // ---- the whole darkened a little toward the edges (his advice to
    // Carus for a moonlit picture), then varnish and age
    if o.stage("veil", &mut c, &mut rng) {
        let hgt = h;
        c.glaze(&Pigment::transparent(hex("#8f7f6c")), None, move |x, y| {
            let dx = (x - 480.0) / 560.0;
            let dy = (y - hgt * 0.55) / (hgt * 0.62);
            0.55 * smoothstep(0.55, 1.25, (dx * dx + dy * dy).sqrt())
        });
    }

    o.finish(&mut c, &mut rng, &Finish::aged(st.relief));
}

